`default_nettype none

// skid_buffer: two-register valid/ready register slice.
// Implements microarchitecture.md section 3 for the ports of interface_spec.md.
// Every output is a flop (s_ready is the inverse of one); the inputs reach
// only the next-state logic.
module skid_buffer #(
    parameter WIDTH = 8
) (
    input  wire             clk,
    input  wire             rst_n,
    input  wire             s_valid,
    output wire             s_ready,
    input  wire [WIDTH-1:0] s_data,
    output reg              m_valid,
    input  wire             m_ready,
    output reg  [WIDTH-1:0] m_data
);

    reg             skid_valid;
    reg [WIDTH-1:0] skid_data;

    wire m_free;
    wire s_fire;

    assign s_ready = ~skid_valid;
    assign m_free  = ~m_valid | m_ready;
    assign s_fire  = s_valid & s_ready;

    reg             m_valid_d;
    reg [WIDTH-1:0] m_data_d;
    reg             skid_valid_d;
    reg [WIDTH-1:0] skid_data_d;

    // Next state (microarchitecture.md section 3).
    always @(*) begin
        m_valid_d    = m_valid;
        m_data_d     = m_data;
        skid_valid_d = skid_valid;
        skid_data_d  = skid_data;
        if (m_free) begin
            if (skid_valid) begin
                // The skid beat moves to the output register.
                m_valid_d    = 1'b1;
                m_data_d     = skid_data;
                skid_valid_d = 1'b0;
            end else begin
                // Output register loads straight from the input.
                m_valid_d = s_valid;
                m_data_d  = s_data;
            end
        end else if (s_fire) begin
            // Output stalled: the accepted beat goes to the skid register.
            skid_valid_d = 1'b1;
            skid_data_d  = s_data;
        end
    end

    // Control registers: synchronous active-low reset.
    always @(posedge clk) begin
        if (!rst_n) begin
            m_valid    <= 1'b0;
            skid_valid <= 1'b0;
        end else begin
            m_valid    <= m_valid_d;
            skid_valid <= skid_valid_d;
        end
    end

    // Data registers: not reset (microarchitecture.md section 2).
    always @(posedge clk) begin
        m_data    <= m_data_d;
        skid_data <= skid_data_d;
    end

`ifdef FORMAL
    // Design-intent properties: the ports behave as a queue of up to two
    // beats. Not proven by any job file in this submission.
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    always @(*) if (!f_past_valid) assume(!rst_n);

    wire f_push = s_valid & s_ready;
    wire f_pop  = m_valid & m_ready;

    reg [1:0]       f_count;
    reg [WIDTH-1:0] f_q0;
    reg [WIDTH-1:0] f_q1;

    always @(posedge clk) begin
        if (!rst_n) begin
            f_count <= 2'd0;
        end else begin
            if (f_push && !f_pop)
                f_count <= f_count + 2'd1;
            else if (!f_push && f_pop)
                f_count <= f_count - 2'd1;
            if (f_pop) begin
                if (f_push && (f_count == 2'd1))
                    f_q0 <= s_data;
                else
                    f_q0 <= f_q1;
            end else if (f_push) begin
                if (f_count == 2'd0)
                    f_q0 <= s_data;
                else
                    f_q1 <= s_data;
            end
        end
    end

    always @(*) begin
        if (f_past_valid) begin
            assert(f_count != 2'd3);
            assert(m_valid == (f_count != 2'd0));
            assert(s_ready == (f_count != 2'd2));
            assert(f_count == ({1'b0, m_valid} + {1'b0, skid_valid}));
            if (m_valid)
                assert(m_data == f_q0);
            if (skid_valid)
                assert(skid_data == f_q1);
        end
    end

    always @(posedge clk) begin
        if (f_past_valid && !$past(rst_n))
            assert(!m_valid && s_ready);
        if (f_past_valid && $past(rst_n) && $past(m_valid) && !$past(m_ready))
            assert(m_valid && (m_data == $past(m_data)));
    end

    always @(posedge clk) begin
        if (f_past_valid && rst_n) begin
            cover(m_valid && !m_ready && s_fire);
            cover(skid_valid);
            cover($past(skid_valid) && !m_valid);
            cover($past(s_fire && f_pop) && s_fire && f_pop);
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
