`timescale 1ns/1ps
`default_nettype none

`define CHK(cond, msg) \
    begin \
        if (cond) passed = passed + 1; \
        else begin \
            failed = failed + 1; \
            $error("FAIL t=%0t: %s", $time, msg); \
        end \
    end

// Self-checking testbench for skid_buffer: a WIDTH 8 lane and a WIDTH 1 lane
// share the control inputs and are checked every cycle against one model.
module skid_buffer_tb;

    reg        clk;
    reg        rst_n;
    reg        s_valid;
    reg        m_ready;
    reg  [7:0] s_data;

    wire       s_ready8;
    wire       m_valid8;
    wire [7:0] m_data8;
    wire       s_ready1;
    wire       m_valid1;
    wire [0:0] m_data1;

    skid_buffer #(.WIDTH(8)) dut8 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready8),
        .s_data  (s_data),
        .m_valid (m_valid8),
        .m_ready (m_ready),
        .m_data  (m_data8)
    );

    skid_buffer #(.WIDTH(1)) dut1 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready1),
        .s_data  (s_data[0]),
        .m_valid (m_valid1),
        .m_ready (m_ready),
        .m_data  (m_data1)
    );

    // Verdict
    integer passed;
    integer failed;
    reg [8*64-1:0] nonce;

    // Model: a queue of up to two beats; q0 is the oldest.
    reg [1:0] cnt;
    reg [1:0] cnt_n;
    reg [7:0] q0;
    reg [7:0] q1;
    reg [7:0] q0_n;
    reg [7:0] q1_n;
    reg       push;
    reg       pop;
    reg       last_push;
    reg       last_pop;
    reg       stall;
    reg       stall_n;
    reg [7:0] stall_data;
    reg [7:0] stall_data_n;
    reg       checking;
    reg       exp_mv;
    reg       exp_sr;

    // Flip-test scratch
    reg       f_sr8;
    reg       f_mv8;
    reg [7:0] f_md8;
    reg       f_sr1;
    reg       f_mv1;
    reg [0:0] f_md1;
    reg       f_sv;
    reg       f_mr;
    reg [7:0] f_sd;

    // Counters
    integer n_push;
    integer n_pop;
    integer n_drop;
    integer cov_full;
    integer cov_flow;
    integer cov_stall_accept;
    integer cov_reject;
    integer cov_drain;
    integer cov_reset_held;

    integer i;
    integer k;
    reg [31:0] r;

    task check_outputs;
        begin
            exp_mv = (cnt != 2'd0);
            exp_sr = (cnt != 2'd2);
            `CHK(m_valid8 === exp_mv, "lane8 m_valid matches the model")
            `CHK(s_ready8 === exp_sr, "lane8 s_ready matches the model")
            `CHK(m_valid1 === exp_mv, "lane1 m_valid matches the model")
            `CHK(s_ready1 === exp_sr, "lane1 s_ready matches the model")
            if (exp_mv) begin
                `CHK(m_data8 === q0, "lane8 m_data is the oldest beat held")
                `CHK(m_data1 === q0[0], "lane1 m_data is the oldest beat held")
            end
            if (stall) begin
                `CHK(m_valid8 === 1'b1 && m_data8 === stall_data, "lane8 hold: stalled beat stays offered unchanged")
                `CHK(m_valid1 === 1'b1 && m_data1 === stall_data[0], "lane1 hold: stalled beat stays offered unchanged")
            end
        end
    endtask

    task flip_test;
        begin
            f_sr8 = s_ready8;
            f_mv8 = m_valid8;
            f_md8 = m_data8;
            f_sr1 = s_ready1;
            f_mv1 = m_valid1;
            f_md1 = m_data1;
            f_sv  = s_valid;
            f_mr  = m_ready;
            f_sd  = s_data;
            s_valid = ~f_sv;
            m_ready = ~f_mr;
            s_data  = ~f_sd;
            #1;
            `CHK(s_ready8 === f_sr8 && s_ready1 === f_sr1, "s_ready does not move with m_ready or s_valid inside a cycle")
            `CHK(m_valid8 === f_mv8 && m_data8 === f_md8 && m_valid1 === f_mv1 && m_data1 === f_md1, "m_valid and m_data do not move with the inputs inside a cycle")
            s_valid = f_sv;
            m_ready = f_mr;
            s_data  = f_sd;
            #1;
        end
    endtask

    task model_compute;
        begin
            push = rst_n && s_valid && (cnt != 2'd2);
            pop  = rst_n && m_ready && (cnt != 2'd0);
            cnt_n = cnt;
            q0_n  = q0;
            q1_n  = q1;
            stall_n      = rst_n && (cnt != 2'd0) && !m_ready;
            stall_data_n = q0;
            if (!rst_n) begin
                cnt_n  = 2'd0;
                n_drop = n_drop + {30'd0, cnt};
                if (cnt != 2'd0) cov_reset_held = cov_reset_held + 1;
            end else if (push && !pop) begin
                if (cnt == 2'd0) q0_n = s_data;
                else             q1_n = s_data;
                cnt_n = cnt + 2'd1;
            end else if (!push && pop) begin
                q0_n  = q1;
                cnt_n = cnt - 2'd1;
            end else if (push && pop) begin
                // Only possible with one beat held.
                q0_n = s_data;
            end
            if (push) n_push = n_push + 1;
            if (pop)  n_pop  = n_pop + 1;
            if (push && pop) cov_flow = cov_flow + 1;
            if (rst_n && (cnt == 2'd1) && !m_ready && s_valid) cov_stall_accept = cov_stall_accept + 1;
            if (rst_n && (cnt == 2'd2) && !m_ready && s_valid) cov_reject = cov_reject + 1;
            if (rst_n && (cnt == 2'd2)) cov_full = cov_full + 1;
            if (rst_n && pop && !push && (cnt_n == 2'd0)) cov_drain = cov_drain + 1;
            last_push = push;
            last_pop  = pop;
        end
    endtask

    task model_apply;
        begin
            cnt        = cnt_n;
            q0         = q0_n;
            q1         = q1_n;
            stall      = stall_n;
            stall_data = stall_data_n;
        end
    endtask

    // One clock: inputs are set by the caller while clk is low.
    task cycle;
        begin
            if (checking) begin
                check_outputs;
                flip_test;
            end else begin
                #2;
            end
            model_compute;
            #3 clk = 1'b1;
            model_apply;
            #5 clk = 1'b0;
        end
    endtask

    initial begin
        passed = 0;
        failed = 0;
        nonce  = {(8*64){1'b0}};
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce[31:0] = "none";

        n_push = 0;
        n_pop = 0;
        n_drop = 0;
        cov_full = 0;
        cov_flow = 0;
        cov_stall_accept = 0;
        cov_reject = 0;
        cov_drain = 0;
        cov_reset_held = 0;

        clk = 1'b0;
        rst_n = 1'b0;
        s_valid = 1'b0;
        m_ready = 1'b0;
        s_data = 8'd0;
        cnt = 2'd0;
        q0 = 8'd0;
        q1 = 8'd0;
        q0_n = 8'd0;
        q1_n = 8'd0;
        cnt_n = 2'd0;
        stall = 1'b0;
        stall_data = 8'd0;
        last_push = 1'b0;
        last_pop = 1'b0;
        checking = 1'b0;
        r = 32'd0;

        // ---------------- Reset values ----------------
        #10;
        cycle;
        checking = 1'b1;
        `CHK(m_valid8 === 1'b0 && m_valid1 === 1'b0, "reset: m_valid low")
        `CHK(s_ready8 === 1'b1 && s_ready1 === 1'b1, "reset: s_ready high")
        s_valid = 1'b1;
        s_data = 8'hEE;
        cycle;
        `CHK(m_valid8 === 1'b0 && s_ready8 === 1'b1, "reset: beat offered during reset is not taken")

        // ---------------- One-cycle latency ----------------
        rst_n = 1'b1;
        s_valid = 1'b1;
        m_ready = 1'b1;
        s_data = 8'hA5;
        `CHK(m_valid8 === 1'b0, "latency: nothing offered before the accepting edge")
        cycle;
        `CHK(m_valid8 === 1'b1 && m_data8 === 8'hA5 && m_data1 === 1'b1, "latency: beat offered on the cycle after it is accepted")
        s_valid = 1'b0;
        cycle;
        `CHK(m_valid8 === 1'b0 && m_valid1 === 1'b0, "latency: slice empty after the beat leaves")

        // ---------------- Full throughput ----------------
        s_valid = 1'b1;
        m_ready = 1'b1;
        for (k = 0; k < 40; k = k + 1) begin
            s_data = k[7:0];
            cycle;
            if (k > 0) begin
                `CHK(last_push && last_pop, "full throughput: one beat in and one out on every edge")
            end
        end
        s_valid = 1'b0;
        cycle;
        cycle;
        `CHK(m_valid8 === 1'b0, "full throughput: stream drains")

        // ---------------- Stall with one and two beats held ----------------
        m_ready = 1'b0;
        s_valid = 1'b1;
        s_data = 8'h11;
        cycle;
        s_data = 8'h22;
        `CHK(s_ready8 === 1'b1 && s_ready1 === 1'b1, "stall: one beat held, s_ready stays high")
        cycle;
        `CHK(cnt == 2'd2 && s_ready8 === 1'b0 && s_ready1 === 1'b0, "stall: second beat accepted, two held, s_ready low")
        s_data = 8'h33;
        cycle;
        `CHK(cnt == 2'd2 && s_ready8 === 1'b0 && m_data8 === 8'h11, "stall: third beat is not accepted")
        for (k = 0; k < 4; k = k + 1) begin
            r = $random;
            s_valid = r[0];
            s_data = r[15:8];
            m_ready = 1'b0;
            cycle;
        end
        m_ready = 1'b1;
        s_valid = 1'b0;
        cycle;
        `CHK(m_valid8 === 1'b1 && m_data8 === 8'h22 && s_ready8 === 1'b1, "ready rises after a stall: second beat is next, s_ready high")
        cycle;
        `CHK(m_valid8 === 1'b0 && m_valid1 === 1'b0, "after a stall every beat left once, in order")

        // ---------------- Stalls inside a stream ----------------
        s_valid = 1'b1;
        for (k = 0; k < 60; k = k + 1) begin
            s_data = 8'h40 + k[7:0];
            m_ready = !((k == 10) || ((k >= 20) && (k < 25)) || (k == 30) || (k == 31));
            cycle;
        end
        s_valid = 1'b0;
        m_ready = 1'b1;
        cycle;
        cycle;
        cycle;
        `CHK(m_valid8 === 1'b0, "stream with stalls drains")

        // ---------------- Random traffic ----------------
        for (i = 0; i < 2000; i = i + 1) begin
            r = $random;
            s_valid = r[0];
            m_ready = r[1];
            s_data = r[15:8];
            rst_n = (r[31:26] != 6'd0);
            cycle;
        end
        rst_n = 1'b1;
        for (i = 0; i < 1500; i = i + 1) begin
            r = $random;
            s_valid = r[0] | r[1];
            m_ready = r[2] | r[3];
            s_data = r[15:8];
            cycle;
        end
        for (i = 0; i < 1500; i = i + 1) begin
            r = $random;
            s_valid = r[0] | r[1];
            m_ready = r[2] & r[3];
            s_data = r[15:8];
            cycle;
        end
        s_valid = 1'b0;
        m_ready = 1'b1;
        cycle;
        cycle;
        cycle;
        `CHK(cnt == 2'd0 && m_valid8 === 1'b0 && m_valid1 === 1'b0 && s_ready8 === 1'b1, "random traffic ends in a drain")

        // ---------------- Reset with beats held ----------------
        m_ready = 1'b0;
        s_valid = 1'b1;
        s_data = 8'h5A;
        cycle;
        s_data = 8'hC3;
        cycle;
        `CHK(cnt == 2'd2 && m_valid8 === 1'b1 && s_ready8 === 1'b0, "reset test: two beats held before reset")
        rst_n = 1'b0;
        s_data = 8'h99;
        cycle;
        `CHK(m_valid8 === 1'b0 && s_ready8 === 1'b1 && m_valid1 === 1'b0 && s_ready1 === 1'b1, "reset drops held beats")
        rst_n = 1'b1;
        s_valid = 1'b1;
        m_ready = 1'b1;
        s_data = 8'h77;
        cycle;
        `CHK(m_valid8 === 1'b1 && m_data8 === 8'h77, "slice works after reset with beats held")
        s_valid = 1'b0;
        cycle;
        cycle;
        `CHK(m_valid8 === 1'b0, "slice idle at the end")

        // ---------------- Bookkeeping and coverage ----------------
        `CHK(n_push == n_pop + n_drop, "every accepted beat left once or was dropped by reset")
        `CHK(cov_full > 0, "coverage: slice full")
        `CHK(cov_flow > 0, "coverage: beat in and out on one edge")
        `CHK(cov_stall_accept > 0, "coverage: beat accepted while the output stalls")
        `CHK(cov_reject > 0, "coverage: beat offered while full")
        `CHK(cov_drain > 0, "coverage: slice drains to empty")
        `CHK(cov_reset_held > 0, "coverage: reset with beats held")

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`default_nettype wire
=== END FILE ===
